import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice builds an invoice with customer, date, and line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const tests = [
    '2024-1-15',
    '2024/01/15',
    '15-01-2024',
    '2024-13-01',
    '2024-01-32',
    '2024-02-30',
    'not-a-date',
    '',
  ];

  for (const date of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Expected failure for date: ${date}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = ['2024-01-31', '2024-02-29', '2025-02-28', '1970-01-01'];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Expected success for date: ${date}`);
  }
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns NO_LINES when lines is missing or null', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
  });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: null,
  });

  assert.equal(result1.ok, false);
  assert.equal(result1.error, 'NO_LINES');
  assert.equal(result2.ok, false);
  assert.equal(result2.error, 'NO_LINES');
});

test('createInvoice returns QTY_INVALID for non-positive quantity', () => {
  const tests = [0, -1, -10];

  for (const qty of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Expected failure for qty: ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  const tests = [1.5, 2.1, 0.5, '5', null, undefined];

  for (const qty of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Expected failure for qty: ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice returns UNKNOWN_SKU for product not in catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice stops at first line validation error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'UNKNOWN', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate the input lines', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  assert.equal(result.ok, true);
  assert.deepEqual(inputLines, [{ sku: 'DES-HOUR', qty: 5 }]);
  assert.notEqual(result.value.lines, inputLines);
});

test('createInvoice includes products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // 21%
      { sku: 'PRINT-A4', qty: 1 }, // 9%
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0%
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with quantity of 1', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 100, unitPrice: 9500 };
  assert.equal(lineTotal(line), 950000);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 42500 + 28500, // 71000
    total: 42500 + 28500,
  });
});

test('invoiceTotals works with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, total: 0 });
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 120000, total: 120000 });
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 8 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.deepEqual(totals, {
    subtotal: 10 * 8500 + 8 * 9500, // 85000 + 76000 = 161000
    total: 10 * 8500 + 8 * 9500,
  });
});

test('addLine adds a new line to a draft invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.deepEqual(addResult.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 8);
});

test('addLine validates qty like createInvoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;

  const zeroResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 0 });
  assert.equal(zeroResult.ok, false);
  assert.equal(zeroResult.error, 'QTY_INVALID');

  const negativeResult = addLine(invoice, { sku: 'DEV-HOUR', qty: -1 });
  assert.equal(negativeResult.ok, false);
  assert.equal(negativeResult.error, 'QTY_INVALID');

  const floatResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 });
  assert.equal(floatResult.ok, false);
  assert.equal(floatResult.error, 'QTY_INVALID');
});

test('addLine validates SKU like createInvoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const addResult = addLine(invoice, { sku: 'UNKNOWN-SKU', qty: 1 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'UNKNOWN_SKU');
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'NOT_DRAFT');
});

test('addLine does not mutate the input invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const originalLines = JSON.stringify(invoice.lines);
  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(addResult.ok, true);
  assert.equal(JSON.stringify(invoice.lines), originalLines);
  assert.notEqual(addResult.value.lines, invoice.lines);
});

test('removeLine removes a line from a draft invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  const invoice = createResult.value;
  const removeResult = removeLine(invoice, 'DES-HOUR');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND for non-existent SKU', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const removeResult = removeLine(invoice, 'UNKNOWN-SKU');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'LINE_NOT_FOUND');
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const removeResult = removeLine(invoice, 'DES-HOUR');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NO_LINES');
});

