      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };

  const removeResult = removeLine(invoice, 'DES-HOUR');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NOT_DRAFT');
});

test('removeLine does not mutate the input invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
