test('issueInvoice assigns next number when some exist', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
